import{_ as a,o as t,c as n,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Client, mod and live","description":"","frontmatter":{"pageId":"developers/client","contentRevision":5},"headers":[],"relativePath":"en/developers/client.md","filePath":"en/developers/client.md"}'),r={name:"en/developers/client.md"};function o(s,e,l,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="client-mod-and-live" tabindex="-1">Client, mod and live <a class="header-anchor" href="#client-mod-and-live" aria-label="Permalink to &quot;Client, mod and live&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Client.Core uses async/cancellable network calls, SharedState for UI and an outbox for unanswered mutations. It has no Verse/RimWorld references. The mod touches game objects only on the main thread: post background results through MainThread.Post. Keep one Harmony patch per method and explain why it exists.</p><p>ThingBlobs transfers pawns/items. Entry into a world with possible ID collisions needs newIds:true and ResetMapIndex before spawning a previously spawned blob. References outside the blob must be reconciled to the receiving world. Pawn equality uses thingIDNumber: never Destroy a deserialized copy equal to a live pawn.</p><p>A live mirror is not an independent simulation. Coop rights over owner pawns differ from ownership of visiting guest pawns; cleanup must not mail owner pawns away.</p><h2 id="client-intent" tabindex="-1">UI intent and the main-thread boundary <a class="header-anchor" href="#client-intent" aria-label="Permalink to &quot;UI intent and the main-thread boundary {#client-intent}&quot;">​</a></h2><p>UI captures selected data and creates intent; Core sends a cancellable request and updates SharedState. Network callbacks must not read/create Verse objects; apply game results through MainThread.Post. Cancelling a wait differs from cancelling an accepted server operation.</p><p>Transfers persist journals and an exact snapshot before mutation. Replay original intent instead of rebuilding goods from the current selection. For receipt, save the delivered map before acknowledging. Core tests do not verify Scribe/ThingBlobs or map loading.</p><h2 id="pawn-lifecycle" tabindex="-1">Pawns: IDs, relations and return <a class="header-anchor" href="#pawn-lifecycle" aria-label="Permalink to &quot;Pawns: IDs, relations and return {#pawn-lifecycle}&quot;">​</a></h2><p>A deserialized pawn can equal a live one by thingIDNumber; destroying the copy may affect the real pawn. On cross-world entry regenerate IDs/map index and reconcile external faction/ideo/policy references. Use existing PawnExit/RelationLedger return paths to preserve bilateral relations and UI caches.</p><p>Distinguish object owner, command-authorized player and map writer. Coop assigns host pawns; live visits transfer guest pawns. Shared cleanup must never mail host pawns to a partner. Verify this with two actual clients.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>RimWorld 1.7 uses Waylith/CoreCLR, not Unity; UnityEngine is a stub. Inspect the actual game type before guessing behavior. Local compilation/unit tests do not replace two real clients for gameplay changes.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./testing">Testing and acceptance</a></li><li><a href="./../players/coop">Persistent shared colony</a></li><li><a href="./protocol">Protocol and idempotency</a></li></ul>',16)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
